).toList()))),if(route!=null&&!navigating)Card(color:panel,child:ListTile(leading:const Icon(Icons.navigation,color:cyan),title:Text('${route!.km.toStringAsFixed(1)} км • ${route!.minutes.round()} мин'),subtitle:Text(selected?.name??'Маршрут'),trailing:FilledButton(onPressed:busy?null:startNavigation,child:const Text('ПОЕХАЛИ')))),if(navigating)Card(color:panel,child:ListTile(leading:const Icon(Icons.stop_circle,color:red),title:Text(arrived?'ПРИБЫТИЕ': '${(remainingMeters/1000).toStringAsFixed(1)} км • ETA ${etaText()}'),subtitle:Text(rerouting?'Перестраиваю маршрут…':'GPS ведёт по маршруту • ${routeDistanceMeters(widget.position!,route!.points).round()} м от линии'),trailing:IconButton(onPressed:()=>setState(()=>navigating=false),icon:const Icon(Icons.stop,color:red))))]))])),if(error!=null)Padding(padding:const EdgeInsets.all(6),child:Text(error!,style:const TextStyle(color:red))),Padding(padding:const EdgeInsets.fromLTRB(16,4,16,8),child:Row(children:[Expanded(child:Text(widget.position==null?'GPS не подключён':'GPS подключён',style:const TextStyle(color:cyan))),const Text('© OpenStreetMap contributors',style:TextStyle(fontSize:10,color:Colors.white54))]))]);}
